// Combined EMULATOR-ONLY change on Z5.
// The 55-byte mirror at 0xa031eeb0 is unchanged. The size editor also writes
// 0x1de1 and 0x1df1 through the same setter, so those two arrays sit in the
// next 16 free bytes. The mode flag is 0xa031eef7, inside the owned tail.
// The session sets the flag on entry and clears it on OK, MENU, S1 and session end.
// Role: behaviour. Do not edit this file after it has run.
// Usage: node26 work/scripts/route_f2.mjs om-emu
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/route_f2.mjs om-emu\n');
  process.exit(2);
}
process.env.OM_EMU_MODEL = 'E147';
const use = (p) => import(pathToFileURL(resolve(checkout, 'emu', p)).href);
const OUT = resolve('work/out/route-f2.jsonl');
const CSV = resolve('work/out/overlay-changed-bytes.csv');
const BASE = 0x60021020;
const GETTER = 0x60063380;
const SETTER = 0x60063431;
const MODE = 0xa031eef7;
const MODE_CACHED = 0x6031eef7;
const PROFILE = 0xa031e920;
const PROFILE_CACHED = 0x6031e920;
const EXT = 0xa031eeb0;
const LAYOUT = {
  0x99a1: { off: 0x00, n: 8, width: 1 },
  0x9a41: { off: 0x08, n: 2, width: 1 },
  0x5962: { off: 0x0a, n: 6, width: 2 },
  0x1dd1: { off: 0x16, n: 10, width: 1 },
  0x84d1: { off: 0x20, n: 1, width: 1 },
  0x88b2: { off: 0x22, n: 1, width: 2 },
  0x90d1: { off: 0x24, n: 8, width: 1 },
  0x5a11: { off: 0x2c, n: 11, width: 1 },
  0x1de1: { off: 0x37, n: 8, width: 1 },
  0x1df1: { off: 0x3f, n: 8, width: 1 },
};
const TITLE = {
  all: '012041e4f3a3879914a8681e55a7ee206f7fe4c1e998177ba0a6f72520bb9d16',
  single: '42a83c79ead5126577e529b063c94c43e6d6d7a3177476b1be78a8c12c09b1a7',
  c1: 'b1b61046dadf4ac4716b1a9fc70a79d4b2a75e46c1373f6eb46707a54a314794',
};

const { loadNand, loadImage, loadBlock, patchedFirmware, createHash: fwHash } = await use('checks/lib/env.mjs');
const { IMAGE_BASE } = await use('src/fw/model.mjs');
const { Player } = await use('src/lab/player.mjs');
const { apply_uiin_layout } = await use('src/lab/play.mjs');
const { PLAYER_PARSER } = await use('scenarios/session_replay.mjs');
const { MenuWalk } = await use('src/lab/menuwalk.mjs');
const { write_png } = await use('checks/lib/png.mjs');
const { words_to_rgb } = await use('src/lab/display.mjs');
const { fileNvram } = await use('host/nvram.mjs');

const image = readFileSync(resolve('inputs/00_0100_50000020.decoded.bin'));
const patches = [];
for (const row of readFileSync(CSV, 'utf8').trim().split(/\r?\n/).slice(1)) {
  const [o, , old, next] = row.split(',');
  const off = parseInt(o, 16);
  if (image[off] !== parseInt(old, 16)) throw new Error('overlay stock mismatch at ' + (BASE + off).toString(16));
  const oldB = parseInt(old, 16);
  const neu = parseInt(next, 16);
  const last = patches.at(-1);
  if (last && off === last.offset + last.old.length) { last.old.push(oldB); last.neu.push(neu); }
  else patches.push({ offset: off, old: [oldB], neu: [neu] });
}
const fw = patchedFirmware(patches.map((x, n) => ({
  block: 'main', offset: x.offset, old: Uint8Array.from(x.old), new: Uint8Array.from(x.neu), source: CSV, n,
})));
apply_uiin_layout(fw.rom);

const lines = [];
const emit = (row) => {
  lines.push(JSON.stringify(row));
  console.log(JSON.stringify({ step: row.step, pass: row.pass, screen: row.screen, flag: row.flag, zone: row.zone, problems: row.problems }));
  mkdirSync(resolve('work/out'), { recursive: true });
  writeFileSync(OUT, lines.join('\n') + '\n');
};
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const native = (address) => (0x50000000 + address - IMAGE_BASE) >>> 0;
function diffCells(a, b, path = '', out = []) {
  if (Array.isArray(a) && Array.isArray(b)) {
    for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) out.push([path + '[' + i + ']', a[i], b[i]]);
    return out;
  }
  if (a && b && typeof a === 'object') {
    for (const k of Object.keys(a)) diffCells(a[k], b[k], path ? path + '.' + k : k, out);
    return out;
  }
  if (a !== b) out.push([path, a, b]);
  return out;
}
function titleHash(frame) {
  const [w, h, words] = frame;
  const y1 = Math.max(1, Math.min(h, Math.floor(h * 0.16)));
  const x0 = Math.floor(w * 0.22);
  const x1 = Math.floor(w * 0.78);
  const buf = Buffer.alloc((x1 - x0) * y1 * 4);
  let o = 0;
  for (let y = 0; y < y1; y++) for (let x = x0; x < x1; x++) { buf.writeUInt32LE(words[y * w + x] >>> 0, o); o += 4; }
  return createHash('sha256').update(buf).digest('hex');
}

let failed = null;
const nvPath = resolve('work/out/nvram-route-f2.json');
try {
  const nv = fileNvram(nvPath);
  const pl = new Player(
    { ...PLAYER_PARSER, no_browser: true, idle: 'off', a15: 'on', out: '<out>', no_wait_on_error: true },
    {
      ...fw, nand: loadNand(), createHash: fwHash, wallClock: () => performance.now() / 1000,
      machine: { coverage: { mark() {}, stub() {} } }, nvram: nv, patch: fw.summary, patchRanges: fw.changed, loaded: 'on',
    },
  );
  pl.camapp_components = true;
  pl.camapp_native_tra = true;
  pl.open_session();
  const s = pl.session;
  const l = s.lab;
  const readByte = (addr) => l.sim.read(addr, 1)[0];
  const writeByte = (addr, value) => { const b = Buffer.alloc(1); b[0] = value & 0xff; l.sim.write(addr, b); };
  const writeU16 = (addr, value) => { const b = Buffer.alloc(2); b.writeUInt16LE(value & 0xffff, 0); l.sim.write(addr, b); };
  const halfWord = (addr) => { const b = l.sim.read(addr, 2); return b[0] | (b[1] << 8); };
  const slotAddr = (key, index) => {
    const spec = LAYOUT[key];
    if (!spec || index < 0 || index >= spec.n) return null;
    return EXT + spec.off + index * spec.width;
  };
  const bootFlag = { uncached: readByte(MODE), cached: readByte(MODE_CACHED) };
  l.hook(native(GETTER), (h, r) => {
    const addr = readByte(MODE) === 1 ? slotAddr(r.d0 & 0xffff, r.d1 & 0xffff) : null;
    if (addr === null) { l.passthrough(r); return; }
    const spec = LAYOUT[r.d0 & 0xffff];
    h.finish(r, { d0: spec.width === 2 ? halfWord(addr) : readByte(addr) });
  }, 'EMULATOR-ONLY combined: AF-ON getter redirect, flag 0xa031eef7');
  l.hook(native(SETTER), (h, r) => {
    const key = r.d0 & 0xffff;
    const index = r.d1 & 0xffff;
    const addr = readByte(MODE) === 1 ? slotAddr(key, index) : null;
    if (addr === null) { l.passthrough(r); return; }
    const spec = LAYOUT[key];
    if (spec.width === 2) writeU16(addr, r.a1 >>> 0);
    else writeByte(addr, r.a1 >>> 0);
    if (key === 0x99a1 && (index === 0 || index === 1)) {
      writeByte(PROFILE, r.a1 & 0xff);
      writeByte(PROFILE_CACHED, r.a1 & 0xff);
    }
    h.finish(r, { d0: 0 });
  }, 'EMULATOR-ONLY combined: AF-ON setter redirect, flag 0xa031eef7');
  const callSaved = (fn) => {
    const saved = l.sim.registers();
    try { return fn(); }
    finally { l.sim.reset(saved); }
  };
  const readKey = (key, index) => callSaved(() => l.call(native(GETTER), { d0: key, d1: index, a0: 0 }, null, null, 200000).d0 & 0xffff);
  const arr = (key, n) => Array.from({ length: n }, (_, i) => readKey(key, i));
  const setMode = (value) => { writeByte(MODE, value); writeByte(MODE_CACHED, value); };
  const cells = () => ({
    profileByte: readByte(PROFILE),
    flag: readByte(MODE),
    k99a1: arr(0x99a1, 8),
    k9a41: arr(0x9a41, 2),
    k5962: arr(0x5962, 6),
    k1dd1: arr(0x1dd1, 10),
    k1de1: arr(0x1de1, 8),
    k1df1: arr(0x1df1, 8),
    k84d1: readKey(0x84d1, 0),
    k88b2: readKey(0x88b2, 0),
    k90d1: arr(0x90d1, 8),
    k5a11: arr(0x5a11, 11),
    k99d2: arr(0x99d2, 3),
    kdfa1: readKey(0xdfa1, 0),
    k9fa1: arr(0x9fa1, 3),
    k90a1: [readKey(0x90a1, 0), readKey(0x90a1, 1)],
  });
  const idle = (ms) => { const to = l.lab_time() + ms * 1e6; while (l.lab_time() < to) s.idle_slice(Math.min(to, l.lab_time() + 50e6)); };
  const key = (k, d) => { s.key(k, d); s.camapp.pump(); };
  const press = (k) => { key(k, 'down'); idle(80); key(k, 'up'); idle(420); };
  const dial = (which, n) => { s.dial_input(which, n); s.camapp.pump(); idle(420); };
  const walk = new MenuWalk({ press, frame: () => s.frame('boundary'), draws: () => l.draw_log }, { limit: 8 });
  let shotN = 0;
  let halfAtEnter = null;
  let last = null;
  const saves = () => (l.store_log?.nvram?.saves ?? []).map((x) => ({ store: x.store, from: x.from, posted: !!x.posted }));
  const snap = (step) => {
    let frame = null;
    let textError = null;
    try { frame = walk.read().frame; }
    catch (e) { textError = String(e && e.message || e); frame = s.frame('boundary'); }
    if (!frame) throw new Error('screenshot failed at ' + step + ': ' + textError);
    const file = resolve('work/out/route-f2-' + String(shotN).padStart(2, '0') + '-' + step + '.png');
    shotN += 1;
    write_png(file, frame[0], frame[1], words_to_rgb(frame[2]));
    const saved = readByte(MODE);
    setMode(0);
    const half = cells();
    setMode(1);
    const prof = cells();
    setMode(saved);
    return { screen: s.screen(), flag: saved, half, prof, title: titleHash(frame), screenshot: file.split(/[/\\]/).pop(), textError };
  };
  const initProfile = () => {
    const zone = 1;
    writeByte(PROFILE, zone);
    writeByte(PROFILE_CACHED, zone);
    for (let i = 0; i < 8; i++) writeByte(EXT + i, i < 2 ? zone : 0);
    writeByte(EXT + 0x08, 0);
    writeByte(EXT + 0x09, 0);
    for (let i = 0; i < 6; i++) writeU16(EXT + 0x0a + i * 2, 500);
    const custom = [1, 1, 4, 6, 3, 3, 3, 3, 3, 3];
    for (let i = 0; i < 10; i++) writeByte(EXT + 0x16 + i, custom[i]);
    writeByte(EXT + 0x20, 0);
    writeU16(EXT + 0x22, 500);
    for (let i = 0; i < 8; i++) writeByte(EXT + 0x24 + i, i < 2 ? zone : 0);
    for (let i = 0; i < 11; i++) writeByte(EXT + 0x2c + i, 1);
    for (let i = 0; i < 8; i++) writeByte(EXT + 0x37 + i, 1);
    const df = [1, 1, 1, 1, 0, 0, 0, 0];
    for (let i = 0; i < 8; i++) writeByte(EXT + 0x3f + i, df[i]);
    setMode(0);
    halfAtEnter = null;
    last = null;
  };
  const run = (step, fn, opts = {}) => {
    if (opts.enter) { setMode(1); halfAtEnter = null; }
    if (fn) fn();
    if (opts.disarm) setMode(0);
    const got = snap(step);
    if (opts.enter) halfAtEnter = got.half;
    const problems = [];
    if (opts.flag !== undefined && got.flag !== opts.flag) problems.push('flag');
    if (opts.screen && got.screen !== opts.screen) problems.push('screen');
    if (opts.title && got.title !== opts.title) problems.push('title');
    if (opts.halfFrozen && halfAtEnter && !same(got.half, halfAtEnter)) problems.push('half-moved');
    if (opts.profHold && last && !same(got.prof, last.prof)) problems.push('prof-moved');
    if (opts.halfMoves && last && same(got.half.k99a1, last.half.k99a1)) problems.push('half-stayed');
    if (opts.profMoves && last && same(got.prof.k99a1, last.prof.k99a1)) problems.push('prof-stayed');
    if (opts.customMoves && last && got.prof.k1dd1[2] === last.prof.k1dd1[2] && got.prof.k1dd1[3] === last.prof.k1dd1[3]) problems.push('custom-stayed');
    emit({
      hook: 'EMULATOR-ONLY', role: 'behaviour', step, pass: problems.length === 0, problems,
      screen: got.screen, flag: got.flag, zone: got.prof.k99a1[1], title: got.title, screenshot: got.screenshot,
      half: got.half, prof: got.prof,
      diffHalf: halfAtEnter ? diffCells(halfAtEnter, got.half) : [],
      diffProf: last ? diffCells(last.prof, got.prof) : [],
    });
    last = got;
    if (problems.length) throw new Error('assertion failed at ' + step + ' ' + problems.join(','));
    return got;
  };
  const toShooting = (tag) => {
    for (let i = 0; i < 6 && s.screen() !== 'shooting'; i++) run(tag + '-' + i, () => press('menu'), { flag: 0, profHold: true });
    if (s.screen() !== 'shooting') throw new Error(tag + ' did not reach shooting');
  };

  emit({
    hook: 'EMULATOR-ONLY', role: 'behaviour', step: 'hooks', pass: bootFlag.uncached === 0xff,
    label: 'Combined: getter 0x60063380 and setter 0x60063431 redirect while 0xa031eef7 is 1. Mirror 0xa031eeb0 stays 55 bytes. 0x1de1 and 0x1df1 follow at 0xa031eee7. Flag cleared on OK, MENU, S1 and session end.',
    bootFlag,
  });
  if (bootFlag.uncached !== 0xff) throw new Error('flag was not 0xFF at boot');
  idle(1000);
  initProfile();

  run('base', null, { flag: 0, screen: 'shooting' });
  run('enter-ok', null, { enter: true, flag: 1, screen: 'shooting' });
  run('ok-up', () => press('up'), { flag: 1, screen: 'direct', title: TITLE.single, halfFrozen: true });
  run('ok-dial', () => dial('main', 1), { flag: 1, screen: 'direct', halfFrozen: true, profMoves: true });
  run('ok-right', () => press('right'), { flag: 1, screen: 'direct', halfFrozen: true });
  run('ok-exit', () => press('ok'), { disarm: true, flag: 0, screen: 'shooting', halfFrozen: true });
  run('normal-after-ok', () => { press('up'); dial('main', 1); }, { flag: 0, screen: 'direct', title: TITLE.single, halfMoves: true, profHold: true });
  run('normal-after-ok-leave', () => press('ok'), { flag: 0, screen: 'shooting', profHold: true });

  initProfile();
  run('enter-menu', null, { enter: true, flag: 1, screen: 'shooting' });
  run('menu-up', () => press('up'), { flag: 1, screen: 'direct', title: TITLE.single, halfFrozen: true });
  run('menu-dial', () => dial('main', 1), { flag: 1, screen: 'direct', halfFrozen: true, profMoves: true });
  run('menu-right', () => press('right'), { flag: 1, screen: 'direct', halfFrozen: true });
  run('menu-exit', () => press('menu'), { disarm: true, flag: 0, halfFrozen: true });
  toShooting('menu-back');
  run('normal-after-menu', () => { press('up'); dial('main', 1); }, { flag: 0, screen: 'direct', halfMoves: true, profHold: true });
  run('normal-after-menu-leave', () => press('ok'), { flag: 0, screen: 'shooting', profHold: true });

  initProfile();
  run('enter-s1', null, { enter: true, flag: 1, screen: 'shooting' });
  run('s1-up', () => press('up'), { flag: 1, screen: 'direct', halfFrozen: true });
  let s1Error = null;
  try { press('s1'); } catch (e) { s1Error = String(e && e.message || e); }
  run('s1-exit', null, { disarm: true, flag: 0, halfFrozen: true });
  if (s1Error) lines[lines.length - 1] = lines[lines.length - 1].replace(/}$/, ',"s1Error":' + JSON.stringify(s1Error) + '}');
  toShooting('s1-back');
  run('normal-after-s1', () => { press('up'); dial('main', 1); }, { flag: 0, screen: 'direct', halfMoves: true, profHold: true });
  run('normal-after-s1-leave', () => press('ok'), { flag: 0, profHold: true });

  initProfile();
  run('size-menu', () => press('menu'), { flag: 0 });
  for (let i = 0; i < 24; i++) {
    let texts = [];
    try { texts = walk.read().texts.map((t) => t.text); } catch { texts = []; }
    if (texts.some((t) => String(t).includes('AF Target Settings'))) break;
    run('size-left-' + i, () => press('left'), { flag: 0 });
  }
  run('size-page', () => press('ok'), { flag: 0 });
  for (let i = 0; i < 5; i++) run('size-down-' + i, () => press('down'), { flag: 0 });
  run('size-enter', null, { enter: true, flag: 1 });
  run('size-right', () => press('right'), { flag: 1, halfFrozen: true });
  run('size-dial-v', () => dial('main', 1), { flag: 1, halfFrozen: true });
  run('size-dial-h', () => dial('sub', 1), { flag: 1, halfFrozen: true });
  run('size-ok', () => press('ok'), { disarm: true, flag: 0, halfFrozen: true, customMoves: true });
  toShooting('size-back');
  run('normal-after-size', () => { press('up'); dial('main', 1); }, { flag: 0, screen: 'direct', halfMoves: true, profHold: true });
  run('normal-after-size-leave', () => press('ok'), { flag: 0, profHold: true });

  const beforeSave = saves();
  for (let i = 0; i < 4 && s.screen() !== 'shooting'; i++) press('menu');
  press('menu');
  idle(600);
  press('menu');
  idle(1000);
  const afterMenu = saves();
  let power = null;
  let powerError = null;
  try { power = s.power_down(); }
  catch (e) { powerError = String(e && e.message || e); }
  const afterPower = saves();
  setMode(0);
  emit({
    hook: 'EMULATOR-ONLY', role: 'behaviour', step: 'save-completion',
    pass: afterPower.length > beforeSave.length || afterMenu.length > beforeSave.length,
    savesBefore: beforeSave, savesAfterMenu: afterMenu, savesAfterPower: afterPower,
    powerNull: power === null, powerError, flag: readByte(MODE),
  });
  if (pl.session) pl.close_session();

  const pl2 = new Player(
    { ...PLAYER_PARSER, no_browser: true, idle: 'off', a15: 'on', out: '<out>', no_wait_on_error: true },
    {
      ...fw, nand: loadNand(), createHash: fwHash, wallClock: () => performance.now() / 1000,
      machine: { coverage: { mark() {}, stub() {} } }, nvram: fileNvram(nvPath), patch: fw.summary, patchRanges: fw.changed, loaded: 'on',
    },
  );
  pl2.camapp_components = true;
  pl2.camapp_native_tra = true;
  pl2.open_session();
  const s2 = pl2.session;
  const l2 = s2.lab;
  const to = l2.lab_time() + 800 * 1e6;
  while (l2.lab_time() < to) s2.idle_slice(Math.min(to, l2.lab_time() + 50e6));
  const mirror = Array.from(l2.sim.read(EXT, 71));
  const flag2 = l2.sim.read(MODE, 1)[0];
  const zone2 = l2.sim.read(PROFILE, 1)[0];
  emit({
    hook: 'EMULATOR-ONLY', role: 'behaviour', step: 'reopen-raw',
    pass: flag2 !== 1 && zone2 === 0,
    flag: flag2, zoneByte: zone2, mirror,
    note: '0xFF in the mirror is the image byte. The zone byte 0 is the Z5 image byte. Neither the edited mirror nor the flag is in the native store.',
  });
  pl2.close_session();
  emit({ hook: 'EMULATOR-ONLY', role: 'behaviour', step: 'done', pass: true, ok: true });
} catch (e) {
  failed = String(e && e.stack ? e.stack : e);
  emit({ hook: 'EMULATOR-ONLY', role: 'behaviour', step: 'done', pass: false, ok: false, error: failed });
  process.exitCode = 1;
} finally {
  writeFileSync(OUT, lines.join('\n') + (lines.length ? '\n' : ''));
}
if (failed) process.exit(1);
